51	const basePremiumOf = (item: Item): number => BASE_PREMIUMS[item.type];
52	
53	const premiumFor = (quote: QuoteStep): number => {
54	  const policyBase = quote.items.reduce((sum, item) => sum + basePremiumOf(item), 0);
55	  return policyBase + policyBase * FIRST_INSURANCE_SURCHARGE + PROCESSING_FEE;
56	};
