58	const resultOf = (step: Step): StepResult => {
59	  if (step.op === "quote") return { premium: premiumFor(step) };
60	  throw new Error(`unsupported step: ${step.op}`);
61	};
62	
63	export const runScenario = (scenario: Scenario): ScenarioResult => ({
64	  results: scenario.steps.map(resultOf),
